mapper.select:
SELECT num, gallery_num,gwriter,member_num,gcontent,elike,reip,gcdate, row_num FROM (
SELECT num, gallery_num,gwriter,member_num,gcontent,elike,reip,gcdate, ROW_NUMBER() 
OVER(ORDER BY num desc) AS row_num FROM gallery_comm where gallery_num=#{num}
) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}
